package br.com.confirmacao.audit.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="audit_logs")public class AuditLog{@Id private UUID id;@Column(name="actor_user_id")private UUID actorUserId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=60)private AuditAction action;@Column(name="resource_type",nullable=false,length=60)private String resourceType;@Column(name="resource_id")private UUID resourceId;@Column(name="ip_address",length=45)private String ipAddress;@Column(name="created_at",nullable=false)private Instant createdAt;protected AuditLog(){}public AuditLog(UUID u,AuditAction a,String t,UUID r,String ip){if(a==null||t==null||t.isBlank())throw new IllegalArgumentException("Dados obrigatórios da auditoria não informados");id=UUID.randomUUID();actorUserId=u;action=a;resourceType=t;resourceId=r;ipAddress=ip;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getActorUserId(){return actorUserId;}public AuditAction getAction(){return action;}public String getResourceType(){return resourceType;}public UUID getResourceId(){return resourceId;}public String getIpAddress(){return ipAddress;}public Instant getCreatedAt(){return createdAt;}}
